create extension if not exists pgcrypto;
create table if not exists profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, created_at timestamptz not null default now());
create table if not exists projects (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, category text not null, location_name text not null, latitude double precision, longitude double precision, claimed_goal text not null, description text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists media (id uuid primary key default gen_random_uuid(), project_id uuid not null references projects(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, cloudinary_public_id text, secure_url text, resource_type text, format text, width integer, height integer, duration numeric, tags jsonb not null default '[]', moderation_status text, exif jsonb, gps_latitude double precision, gps_longitude double precision, captured_at timestamptz, uploaded_at timestamptz not null default now(), caption text, detected_objects jsonb not null default '[]', trust_score numeric, verification_status text, qdrant_point_id text, created_at timestamptz not null default now());
create table if not exists verifications (id uuid primary key default gen_random_uuid(), media_id uuid not null references media(id) on delete cascade, project_id uuid not null references projects(id) on delete cascade, description text, detected_objects jsonb, matches_claim integer, confidence numeric, anomalies jsonb, estimated_progress_stage text, duplicate_detected boolean not null default false, duplicate_media_id uuid, duplicate_similarity numeric, gps_anomaly boolean not null default false, timestamp_anomaly boolean not null default false, reason text, status text, created_at timestamptz not null default now());
create table if not exists stories (id uuid primary key default gen_random_uuid(), project_id uuid not null references projects(id) on delete cascade, headline text, summary text, key_metrics jsonb, narrative jsonb, evidence_ids jsonb, trust_score numeric, created_by uuid references auth.users(id), is_public boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists media_project_idx on media(project_id); create index if not exists media_user_idx on media(user_id); create index if not exists media_captured_idx on media(captured_at); create index if not exists media_status_idx on media(verification_status); create index if not exists media_trust_idx on media(trust_score);
alter table projects enable row level security; alter table media enable row level security; alter table verifications enable row level security; alter table stories enable row level security;
create policy "users own projects" on projects for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "users access project media" on media for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "users access verifications" on verifications for all using (exists (select 1 from projects where projects.id = verifications.project_id and projects.user_id = auth.uid()));
create policy "users access stories" on stories for all using (auth.uid() = created_by or is_public = true) with check (auth.uid() = created_by);
